// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Layout } from '@stdlib/types/blas';

/**
* Interface describing `svander`.
*/
interface Routine {
	/**
	* Generates a single-precision floating-point Vandermonde matrix.
	*
	* @param order - storage layout
	* @param M - number of rows in the matrix `Out`
	* @param N - number of columns in the matrix `Out`
	* @param mode - specifies whether columns should contain powers that are increasing (`1`) or decreasing (`-1`)
	* @param x - input vector
	* @param strideX - stride length for `x`
	* @param out - output matrix
	* @param LDO - stride length for the leading dimension of `Out`
	* @returns output matrix
	*
	* @example
	* var Float32Array = require( '@stdlib/array/float32' );
	*
	* var x = new Float32Array( [ 1.0, 2.0, 3.0 ] );
	* var out = new Float32Array( 9 );
	*
	* svander( 'row-major', 3, 3, -1, x, 1, out, 3 );
	* // out => <Float32Array>[ 1.0, 1.0, 1.0, 4.0, 2.0, 1.0, 9.0, 3.0, 1.0 ]
	*/
	( order: Layout, M: number, N: number, mode: number, x: Float32Array, strideX: number, out: Float32Array, LDO: number ): Float32Array;

	/**
	* Generates a single-precision floating-point Vandermonde matrix using alternative indexing semantics.
	*
	* @param M - number of rows in the matrix `Out`
	* @param N - number of columns in the matrix `Out`
	* @param mode - specifies whether columns should contain powers that are increasing (`1`) or decreasing (`-1`)
	* @param x - input vector
	* @param strideX - stride length for `x`
	* @param offsetX - starting index for `x`
	* @param out - output matrix
	* @param strideOut1 - stride of the first dimension of `Out`
	* @param strideOut2 - stride of the second dimension of `Out`
	* @param offsetOut - starting index for `Out`
	* @returns output matrix
	*
	* @example
	* var Float32Array = require( '@stdlib/array/float32' );
	*
	* var x = new Float32Array( [ 1.0, 2.0, 3.0 ] );
	* var out = new Float32Array( 9 );
	*
	* svander.ndarray( 3, 3, -1, x, 1, 0, out, 3, 1, 0 );
	* // out => <Float32Array>[ 1.0, 1.0, 1.0, 4.0, 2.0, 1.0, 9.0, 3.0, 1.0 ]
	*/
	ndarray( M: number, N: number, mode: number, x: Float32Array, strideX: number, offsetX: number, out: Float32Array, strideOut1: number, strideOut2: number, offsetOut: number ): Float32Array;
}

/**
* Generates a single-precision floating-point Vandermonde matrix.
*
* @param order - storage layout
* @param M - number of rows in the matrix `Out`
* @param N - number of columns in the matrix `Out`
* @param mode - specifies whether columns should contain powers that are increasing (`1`) or decreasing (`-1`)
* @param x - input vector
* @param strideX - stride length for `x`
* @param out - output matrix
* @param LDO - stride length for the leading dimension of `Out`
* @returns output matrix
*
* @example
* var Float32Array = require( '@stdlib/array/float32' );
*
* var x = new Float32Array( [ 1.0, 2.0, 3.0 ] );
* var out = new Float32Array( 9 );
*
* svander( 'row-major', 3, 3, -1, x, 1, out, 3 );
* // out => <Float32Array>[ 1.0, 1.0, 1.0, 4.0, 2.0, 1.0, 9.0, 3.0, 1.0 ]
*
* @example
* var Float32Array = require( '@stdlib/array/float32' );
*
* var x = new Float32Array( [ 1.0, 2.0, 3.0 ] );
* var out = new Float32Array( 9 );
*
* svander.ndarray( 3, 3, -1, x, 1, 0, out, 3, 1, 0 );
* // out => <Float32Array>[ 1.0, 1.0, 1.0, 4.0, 2.0, 1.0, 9.0, 3.0, 1.0 ]
*/
declare var svander: Routine;


// EXPORTS //

export = svander;
